import React, { useState } from "react";
import styled from "styled-components";
import { apiUserLogin } from "../service/user";
import { loginSuccess } from "../redux/userSlice"; 
import { useDispatch } from "react-redux";
import { useNavigate } from 'react-router-dom';
import { useNotice } from "../context/NoticeContext";
import { useTranslation } from "react-i18next";

const Container = styled.div`
  max-width: 400px;
  margin: 40px auto 10px;
  padding: 20px;
  background: white;
  border-radius: 8px;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
`;

const Title = styled.h2`
  text-align: center;
  font-size: 40px;
  font-weight: bold;
  margin-bottom: 20px;
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const Input = styled.input`
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
  font-size: 16px;
`;

const Button = styled.button`
  width: 100%;
  padding: 10px;
  background: #007bff;
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 16px;

  &:hover {
    background: #0056b3;
  }
`;

const ErrorText = styled.p`
  color: red;
  font-size: 12px;
`;

const LangSwitcher = styled.div`
  text-align: right;
  margin-bottom: 10px;

  button {
    border: none;
    background: transparent;
    cursor: pointer;
    color: #007bff;
    font-size: 14px;
  }
`;

const AuthForm = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { showNotice } = useNotice();
  const { t, i18n } = useTranslation();

  const [formData, setFormData] = useState({
    email: "",
    password: "",
  });

  const [errors, setErrors] = useState({});

  const validateLogin = () => {
    const newErrors = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test(formData.email)) {
      newErrors.email = t("authForm.invalid_email");
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateLogin()) return;

    try {
      const response = await apiUserLogin(formData);
      if (response.status === 1) {
        dispatch(loginSuccess({
          userId: response.data.user._id,
          token: response.data.token,
          role: response.data.user.role,
          isLogin: true,
        }));
        showNotice(1, t("authForm.login_success"));
        navigate("/");
      } else {
        showNotice(0, t("authForm.login_failed"));
      }
    } catch (error) {
      showNotice(0, t("authForm.system_error"));
    }
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const toggleLang = () => {
    const newLang = i18n.language === "vi" ? "en" : "vi";
    i18n.changeLanguage(newLang);
  };

  return (
    <Container>
      <LangSwitcher>
        <button onClick={toggleLang}>
          {i18n.language === "vi" ? "English" : "Tiếng Việt"}
        </button>
      </LangSwitcher>
      <Title>{t("authForm.title")}</Title>
      <Form onSubmit={handleSubmit}>
        <Input
          name="email"
          value={formData.email}
          onChange={handleChange}
          placeholder={t("authForm.email_placeholder")}
        />
        <ErrorText>{errors.email}</ErrorText>

        <Input
          name="password"
          type="password"
          value={formData.password}
          onChange={handleChange}
          placeholder={t("authForm.password_placeholder")}
        />
        <ErrorText>{errors.password}</ErrorText>

        <Button type="submit">{t("authForm.login_button")}</Button>
      </Form>
    </Container>
  );
};

export default AuthForm;
